Q: Horizontal scrolling list currently displaying vertically with scroll A: <p>I created the below component which works similar to your requirement, but it uses Next.js:
<a href="https://i.sstatic.net/trDC0vsy.png" rel="nofollow noreferrer"><img src="https://i.sstatic.net/trDC0vsy.png" alt="image showing horizontally-aligned squares" /></a></p>
<p>Code:</p>
<pre><code>import { Img } from &quot;@/Widgets/Img&quot;;
import React from &quot;react&quot;;

interface ImgSliderProps {
    imgUrls: string[];
    parentHeight?: number;
    imgHeight?: number;
    imgWidth?: number;
    borderRadius?: number;
    onImageClick?: (imgUrl: string, idx: number) =&gt; void;
    showScrollbar?: boolean;
}

export const ImgSlider: React.FC&lt;ImgSliderProps&gt; = ({
    imgUrls,
    parentHeight = 108,
    imgHeight = 100,
    imgWidth = 100,
    borderRadius = 8,
    onImageClick,
    showScrollbar = true,
}) =&gt; {
    const [selectedIdx, setSelectedIdx] = React.useState&lt;number&gt;(0);
    const scrollRef = React.useRef&lt;HTMLDivElement&gt;(null);

    React.useEffect(() =&gt; {
        const slider = scrollRef.current;
        if (!slider) return;

        let isDown = false;
        let startX = 0;
        let scrollLeft = 0;

        const onMouseDown = (e: MouseEvent) =&gt; {
            isDown = true;
            slider.classList.add(&quot;dragging&quot;);
            startX = e.pageX - slider.getBoundingClientRect().left;
            scrollLeft = slider.scrollLeft;
            document.body.style.userSelect = &quot;none&quot;;
        };
        const onMouseMove = (e: MouseEvent) =&gt; {
            if (!isDown) return;
            e.preventDefault();
            const x = e.pageX - slider.getBoundingClientRect().left;
            const walk = x - startX;
            slider.scrollLeft = scrollLeft - walk;
        };
        const onMouseUp = () =&gt; {
            isDown = false;
            slider.classList.remove(&quot;dragging&quot;);
            document.body.style.userSelect = &quot;&quot;;
        };
        const onMouseLeave = () =&gt; {
            isDown = false;
            slider.classList.remove(&quot;dragging&quot;);
            document.body.style.userSelect = &quot;&quot;;
        };

        slider.addEventListener(&quot;mousedown&quot;, onMouseDown);
        slider.addEventListener(&quot;mousemove&quot;, onMouseMove);
        slider.addEventListener(&quot;mouseup&quot;, onMouseUp);
        slider.addEventListener(&quot;mouseleave&quot;, onMouseLeave);

        return () =&gt; {
            slider.removeEventListener(&quot;mousedown&quot;, onMouseDown);
            slider.removeEventListener(&quot;mousemove&quot;, onMouseMove);
            slider.removeEventListener(&quot;mouseup&quot;, onMouseUp);
            slider.removeEventListener(&quot;mouseleave&quot;, onMouseLeave);
        };
    }, []);

    if (!imgUrls || imgUrls.length === 0) return null;

    return (
        &lt;div style={{ width: '100%' }}&gt;
            &lt;div
                ref={scrollRef}
                style={{
                    display: 'flex',
                    flexDirection: 'row',
                    gap: '8px',
                    overflowX: 'auto',
                    padding: '12px 0 16px 0',
                    width: '100%',
                    alignItems: 'center',
                    height: parentHeight,
                    WebkitOverflowScrolling: 'touch',
                    msOverflowStyle: 'auto',
                    scrollbarWidth: showScrollbar ? 'auto' : 'none', // hide native scrollbar if false
                    maxWidth: '100vw',
                    cursor: 'grab',
                }}
                className={`img-slider-scrollbar${showScrollbar ? '' : ' hide-scrollbar'}`}
            &gt;
                {imgUrls.map((imgUrl, idx) =&gt; (
                    &lt;button
                        key={imgUrl + idx}
                        aria-label={`View image number ${idx + 1}`}
                        type=&quot;button&quot;
                        style={{
                            position: 'relative',
                            height: imgHeight,
                            width: imgWidth,
                            minWidth: imgWidth,
                            minHeight: imgHeight,
                            flexShrink: 0,
                            overflow: 'hidden',
                            borderRadius: '0.5rem',
                            border: `2px solid ${idx === selectedIdx ? 'hsl(0,0%,20%)' : 'transparent'}`,
                            transition: 'border 0.3s',
                            outline: 'none',
                            background: 'none',
                            padding: 0,
                            cursor: 'pointer',
                            boxSizing: 'border-box',
                        }}
                        tabIndex={0}
                        onClick={() =&gt; {
                            setSelectedIdx(idx);
                            onImageClick?.(imgUrl, idx);
                        }}
                    &gt;
                        &lt;div
                            style={{
                                opacity: idx === selectedIdx ? 1 : 0.7,
                                transition: 'opacity 0.3s',
                                height: '100%',
                                width: '100%',
                            }}
                        &gt;
                            &lt;Img
                                imgUrl={imgUrl}
                                alt=&quot;&quot;
                                height={imgHeight}
                                width={imgWidth}
                                borderRadius={borderRadius}
                            /&gt;
                        &lt;/div&gt;
                    &lt;/button&gt;
                ))}
            &lt;/div&gt;
        &lt;/div&gt;
    );
};
</code></pre>
<p>Add below lines to globals.css file:</p>
<pre><code>/* Webkit Scrollbar Styles */
.img-slider-scrollbar::-webkit-scrollbar {
  height: 8px;
  background: #eee;
}

.img-slider-scrollbar::-webkit-scrollbar-thumb {
  background: #bbb;
  border-radius: 4px;
}

.img-slider-scrollbar.dragging {
  cursor: grabbing !important;
}
</code></pre>

Q: how to pass html table data to controller using jquery in asp.net mvc razor? A: <p>I got the solution for passing the table data to the controller by doing the following:</p>

<pre><code>$('#btnSaving').click(function(){
   var myTableArray = [];

   $('#tblSavingColl tr:not(:first)').each(function () {
        var tds = $(this).find('td');

        var myDets= { collSheetNo: $('#').val(), clientNo: $(tds[0]).html() }
        myTableArray.push(myDets);
    })

    $.ajax({
        type: 'POST',
        url: '@Url.Action("SaveSavingColln", "CollectionSheetTranscation")',
        dataType: 'json',
        contentType: 'application/json; charset=utf-8',
        data: JSON.stringify(myTableArray),
        success: function (result) {
            alert(result);
        },
        error: function () {
            alert("Error while saving Saving Collection Sheet");
        }
    });
});
</code></pre>

Q: How to convert an Object to array in php with framework Codeigniter A: <p>Using codeigniter, you really should consider using it's 'active record':</p>

<pre><code> $sql="SELECT * FROM cli_articles WHERE ID='{$id}'";
 $response=$this-&gt;db-&gt;query($sql);  
</code></pre>

<p>I would instead suggest:</p>

<pre><code> $this-&gt;db-&gt;select('*'); 
 $this-&gt;db-&gt;where('id', $id); 
 $response = $this-&gt;db-&gt;get('cli_articles')-&gt;result_array(); // for array, result() for object, row() for a single result object, row_array() for a single array 
</code></pre>

<p>But if you want to keep your style:</p>

<pre><code> $sql="SELECT * FROM cli_articles WHERE ID='{$id}'";
 $response=$this-&gt;db-&gt;query($sql);  
 $view_data['results'] = $response-&gt;result_array(); 
 $this-&gt;load-&gt;view("show",$view_data);
</code></pre>

<p>And in your view:</p>

<pre><code>&lt;?= $results['id']; // or you made need to loop, depending on your array structure ?&gt; 
</code></pre>

